let language = (() => {try {return localStorage.getItem('pa-language') === 'en' ? 'en' : 'zh';} catch {return 'zh';}})();
export const getLanguage = () => language;
export function translateText(value, lang = language) {
  if (lang !== 'en') return value;
  const trimmed = value.trim();
  if (dictionary[trimmed]) return value.replace(trimmed, dictionary[trimmed]);
  if (trimmed.endsWith('.') && dictionary[trimmed.slice(0,-1)]) return value.replace(trimmed, dictionary[trimmed.slice(0,-1)] + '.');
  const patterns = [
    [/^全部文献 · (\d+) 篇$/,(_,n)=>`All papers · ${n}`],
    [/^(\d+) 个节点 · (\d+) 条关联$/,(_,n,m)=>`${n} nodes · ${m} connections`],
    [/^删除 (.+) 的账户、头像、全部论文与 API 令牌，无法恢复。$/,(_,name)=>`Permanently delete ${name}, their avatar, papers and API tokens. This cannot be undone.`],
    [/^永久删除“(.+)”的 PDF、元数据和解析结果，无法恢复。$/,(_,title)=>`Permanently delete the PDF, metadata and analysis for “${title}”. This cannot be undone.`],
    [/^已选 (\d+) 篇$/, (_, n) => `${n} selected`],
    [/^(全部文献|我的收藏|待解析) (\d+)$/, (_, label, n) => `${dictionary[label]} ${n}`],
    [/^显示 (\d+)–(\d+) 条，共 (\d+) 篇文献(.*)$/, (_, a, b, n) => `Showing ${a}–${b} of ${n} papers`],
    [/^(\d+) 篇文献$/, (_, n) => `${n} papers`],
    [/^第 (\d+) 页$/, (_, n) => `Page ${n}`],
    [/^(.+) 的论文$/, (_, name) => `Papers by ${name}`],
    [/^已选择 (\d+) 篇$/, (_, n) => `${n} selected`],
    [/^已选择 (\d+) 篇 PDF(.*)$/, (_, n, rest) => `${n} PDFs selected${rest ? ' (some items skipped)' : ''}`],
    [/^已合并 (\d+) 页(.*)$/, (_, n, rest) => `Combined ${n} pages${rest ? '; some papers could not be merged' : ''}`]
  ];
  for (const [pattern, replacement] of patterns) if (pattern.test(trimmed)) return trimmed.replace(pattern, replacement);
  const fragments = {'文献已保存':'Papers saved','先上传全部文件':'Upload all files first','并行 AI 分析（最多 3 篇）':'Analyze papers in parallel (up to 3)','整理双语关键词':'Organize bilingual keywords','已使用 · 配额见后端':'used · project quota applies','篇共同论文':'shared papers','篇论文':'papers','已选文献':'selected papers','当前筛选结果':'current results','已选':'selected','选择 ':'Select ','收藏 ':'Favorite ','构建网络':'Build network','查看全部':'Show all','导出网络':'Export network','重置布局':'Reset layout','隐藏标签':'Hide labels','显示标签':'Show labels','成员':'members','个节点':'nodes','条连线':'edges','到期':'expires','恢复':'Restore','未识别':'Unknown','未发表':'Unpublished','双语扩展：':'Bilingual expansion: ','处理中':'Processing'};
  let translated = value;
  for (const [from, to] of Object.entries(fragments)) translated = translated.replaceAll(from, to);
  return translated;
}
export function setLanguage(next) {
  language = next === 'en' ? 'en' : 'zh';
  try {localStorage.setItem('pa-language', language);} catch {}
  if (typeof document !== 'undefined') {document.documentElement.lang = language === 'en' ? 'en' : 'zh-CN'; document.dispatchEvent(new Event('pa-language-change'));}
}
export function installI18n() {
  const originals = new WeakMap(), attributes = new WeakMap(); let pending = false;
  function update() {
    pending = false; document.documentElement.lang = language === 'en' ? 'en' : 'zh-CN';
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let node; (node = walker.nextNode());) {
      if (node.parentElement?.closest('script,style,textarea,pre,code,.summary,.paper-title,.paper-authors,.keyword-chip,.key-once,[data-user-content],[data-language-toggle]')) continue;
      if (!originals.has(node)) originals.set(node, node.data);
      const next = translateText(originals.get(node)); if (node.data !== next) node.data = next;
    }
    document.querySelectorAll('[placeholder],[title],[aria-label],[alt]').forEach(el => {
      let original = attributes.get(el); if (!original) {original = {}; attributes.set(el, original);}
      for (const name of ['placeholder','title','aria-label','alt']) if (el.hasAttribute(name)) {
        if (!(name in original)) original[name] = el.getAttribute(name);
        const next = translateText(original[name]); if (el.getAttribute(name) !== next) el.setAttribute(name, next);
      }
    });
    document.querySelectorAll('[data-summary-heading]').forEach(el=>{const zh=el.dataset.summaryHeading;const en={'问题':'Question','模型':'Model','模型与方法':'Model and methods','结论与现象':'Findings','局限与待核验':'Limitations and checks'}[zh]||zh;const next=(language==='en'?en:zh)+(language==='en'?':':'：');if(el.textContent!==next)el.textContent=next;});
    document.querySelectorAll('[data-language-toggle]').forEach(button => {const label = language === 'en' ? '中文' : 'English'; if (button.textContent !== label) button.textContent = label;});
  }
  const observer = new MutationObserver(() => {if (!pending) {pending = true; queueMicrotask(update);}});
  observer.observe(document.body, {childList:true,subtree:true,characterData:true});
  document.addEventListener('click', event => {if (event.target.closest('[data-language-toggle]')) setLanguage(language === 'en' ? 'zh' : 'en');});
  document.addEventListener('pa-language-change', update); update();
}
